import java.util.*;

class Solution {
    public int subarraysDivByK(int[] nums, int k) {
        int[] cnt = new int[k];
        cnt[0] = 1;                       // empty prefix
        int mod = 0, total = 0;
        for (int x : nums) {
            mod = ((mod + x) % k + k) % k; // keep the remainder non-negative
            total += cnt[mod];             // earlier prefixes with the same remainder
            cnt[mod]++;
        }
        return total;
    }
}

